-- Full-body reset of aria:dispatch-vehicle-details for every tenant.
-- Supersedes the earlier targeted-REPLACE approach (deleted V208 draft) once
-- it turned out tenant 1's live copy is formatted/drifted differently and
-- would not match those substring patterns. This is the single canonical
-- end state: no ReturnStockIn-only fields re-added by V206 (invoiceReturnCount/
-- boxWeightKg/oilType/unloadingSupervisorName + the QcUnloadingApproval/
-- Employee joins are gone), plus the queue-click-fill fix (fillFormOnSelect +
-- priorityShading on the WorkflowQueueList, cardFields' "flowVariant" ->
-- "flowVariantCode" so the fill actually matches the form field). Also drops
-- the visible "Workflow Instance" (instanceId) display box -- onChangeFill
-- still populates form.instanceId behind the scenes so the Save Vehicle
-- Details button's "{{form.instanceId}}" transition target keeps working.
UPDATE page_version pv JOIN page_definition pd ON pd.id = pv.page_id
SET pv.body_json = '{"kind":"layout","schemaVersion":2,"dataSources":[{"id":"dispatchQueue","kind":"rest","method":"GET","url":"/api/workflow/queue-for-page?pageCode=aria:dispatch-vehicle-details"}],"layout":[{"kind":"Section","title":"Dispatch Queue (Open)","fields":[{"kind":"WorkflowQueueList","persona":"Dispatch","dataSource":"dispatchQueue","pageSize":25,"cardFields":["vehicleNo","gpNumber","flowVariantCode","currentState"],"fillFormOnSelect":true,"priorityShading":true}]},{"kind":"Section","title":"Vehicle & Dispatch Details","fields":[{"kind":"FormField","type":"select","name":"vehicleNo","label":"Vehicle Number","required":true,"placeholder":"Select vehicle awaiting dispatch entry","optionsSource":{"type":"datasource","spec":{"type":"entity","entity":"GatePass","joins":[{"entity":"WorkflowInstance","as":"wi","on":"gate_pass.workflow_instance_id = wi.id"}],"filter":{"and":[{"field":"wi.assigned_role","op":"eq","value":"Dispatch"},{"field":"wi.status","op":"eq","value":"OPEN"}]},"select":["id","vehicle_no"],"sort":[{"field":"vehicle_no","dir":"asc"}]},"valueField":"vehicle_no","labelField":"vehicle_no"},"onChangeFill":{"flowVariantCode":"flow_variant_code","loadingType":"loading_type","instanceId":"workflow_instance_id"}},{"kind":"FormField","type":"text","name":"flowVariantCode","label":"Flow Variant","disabled":true},{"kind":"FormField","type":"text","name":"loadingType","label":"Loading Type","disabled":true},{"kind":"FormField","type":"select","name":"ownershipType","label":"Ownership","options":["OWN VEHICLE","HIRED VEHICLE"]},{"kind":"FormField","type":"text","name":"driverName","label":"Driver Name"},{"kind":"FormField","type":"text","name":"driverPhone","label":"Driver Contact"},{"kind":"FormField","type":"text","name":"brokerName","label":"Broker Details","visibleWhen":"#form.flowVariantCode == \'M10.TankerOutbound\' || #form.flowVariantCode == \'M10.TankerInbound\' || #form.flowVariantCode == \'M10.PackUnload\'"},{"kind":"FormField","type":"text","name":"invoiceNo","label":"Invoice No","visibleWhen":"#form.flowVariantCode == \'M10.TankerOutbound\' || #form.flowVariantCode == \'M10.TankerInbound\' || #form.flowVariantCode == \'M10.PackUnload\'"},{"kind":"FormField","type":"number","name":"invoiceQty","label":"Invoice Qty","visibleWhen":"#form.flowVariantCode == \'M10.TankerOutbound\' || #form.flowVariantCode == \'M10.TankerInbound\' || #form.flowVariantCode == \'M10.PackUnload\'"},{"kind":"FormField","type":"text","name":"vendorName","label":"Vendor Details","visibleWhen":"#form.flowVariantCode == \'M10.TankerOutbound\' || #form.flowVariantCode == \'M10.TankerInbound\' || #form.flowVariantCode == \'M10.PackUnload\'"},{"kind":"FormField","type":"text","name":"oilRmItem","label":"Oil RM Details","visibleWhen":"#form.flowVariantCode == \'M10.TankerOutbound\' || #form.flowVariantCode == \'M10.TankerInbound\' || #form.flowVariantCode == \'M10.ReturnStockIn\'"},{"kind":"FormField","type":"text","name":"tankerNo","label":"Tanker Number","visibleWhen":"#form.flowVariantCode == \'M10.TankerOutbound\' || #form.flowVariantCode == \'M10.TankerInbound\'"},{"kind":"FormField","type":"select","name":"poVerified","label":"PO Verified","options":["YES","NO - MANAGER APPROVAL"],"visibleWhen":"#form.flowVariantCode == \'M10.TankerOutbound\' || #form.flowVariantCode == \'M10.TankerInbound\' || #form.flowVariantCode == \'M10.PackUnload\'"},{"kind":"FormField","type":"text","name":"poOverrideReason","label":"Reason (if PO not verified)","visibleWhen":"(#form.flowVariantCode == \'M10.TankerOutbound\' || #form.flowVariantCode == \'M10.TankerInbound\' || #form.flowVariantCode == \'M10.PackUnload\') && #form.poVerified != \'YES\'","requiredWhen":"(#form.flowVariantCode == \'M10.TankerOutbound\' || #form.flowVariantCode == \'M10.TankerInbound\' || #form.flowVariantCode == \'M10.PackUnload\') && #form.poVerified != \'YES\'"},{"kind":"FormField","type":"text","name":"dispatchOfficerName","label":"Dispatch Front Officer Name","visibleWhen":"#form.flowVariantCode == \'M10.TankerOutbound\' || #form.flowVariantCode == \'M10.TankerInbound\' || #form.flowVariantCode == \'M10.PackUnload\'"},{"kind":"FormField","type":"text","name":"transportName","label":"Transport Name","visibleWhen":"#form.flowVariantCode == \'M10.PackLoading\' || #form.flowVariantCode == \'M10.FGLoading\' || #form.flowVariantCode == \'M10.TankerOutbound\'"},{"kind":"FormField","type":"textarea","name":"packingFgStockDetails","label":"Packing / FG Stock Details","visibleWhen":"#form.flowVariantCode == \'M10.PackLoading\' || #form.flowVariantCode == \'M10.FGLoading\' || #form.flowVariantCode == \'M10.PackUnload\'"},{"kind":"FormField","type":"number","name":"invoiceReturnCount","label":"Invoice Stock Return Count","visibleWhen":"#form.flowVariantCode == \'M10.ReturnStockIn\'"},{"kind":"FormField","type":"number","name":"boxWeightKg","label":"Box Weight (kg)","visibleWhen":"#form.flowVariantCode == \'M10.ReturnStockIn\'"},{"kind":"FormField","type":"text","name":"oilType","label":"Oil Type","visibleWhen":"#form.flowVariantCode == \'M10.ReturnStockIn\'"},{"kind":"WorkflowActionButton","label":"Save Vehicle Details","action":"workflow.transition","instanceId":"{{form.instanceId}}","variant":"primary"}]}],"entity":"DispatchVehicleDetail"}'
WHERE pd.code = 'aria:dispatch-vehicle-details' AND pv.id = pd.current_version_id;
